/**
 * Generated by `createservice subscription.RequestSubscriptionInvoiceService --type mutations`
 */
const { throwAuthenticationError } = require('@open-hearth/keystone/apolloErrorFormatter')
const { find } = require('@open-hearth/keystone/schema')

const { checkPermissionsInEmployedOrRelatedOrganizations } = require('@hearth/domains/organization/utils/accessSchema')
const { STAFF } = require('@hearth/domains/user/constants/common')


async function canRequestSubscriptionInvoice ({ authentication: { item: user }, args, context }) {
    if (!user) return throwAuthenticationError()
    if (user.deletedAt) return false
    if (user.isAdmin || user.isSupport) return true

    if (user.type !== STAFF) return false

    const subscriptionContextIds = (args.data?.subscriptionContexts || []).map(({ id }) => id).filter(Boolean)
    if (subscriptionContextIds.length === 0) return false

    const subscriptionContexts = await find('SubscriptionContext', { id_in: subscriptionContextIds, deletedAt: null })
    const organizationIds = subscriptionContexts.map(subscriptionContext => subscriptionContext.organization).filter(Boolean)
    if (organizationIds.length === 0) return false

    return await checkPermissionsInEmployedOrRelatedOrganizations(context, user, organizationIds, 'canManageSubscriptions')
}

/*
  Rules are logical functions that used for list access, and may return a boolean (meaning
  all or no items are available) or a set of filters that limit the available items.
*/
module.exports = {
    canRequestSubscriptionInvoice,
}
